 IF NOT EXISTS(SELECT FROM storage.buckets WHERE id='specialist-media' AND NOT public AND file_size_limit=5242880 AND allowed_mime_types @> ARRAY['image/png','image/jpeg','image/webp']::text[] AND allowed_mime_types <@ ARRAY['image/png','image/jpeg','image/webp']::text[]) THEN RAISE EXCEPTION 'Bucket configuration drift'; END IF;
 IF NOT EXISTS(SELECT FROM pg_index i WHERE i.indexrelid=to_regclass('public.specialist_orphan_authorization_once') AND i.indrelid='public.specialist_upload_audit'::regclass AND i.indisunique AND i.indisvalid AND pg_get_indexdef(i.indexrelid) LIKE '%evidence%authorization_id%orphan_begin%') THEN RAISE EXCEPTION 'Orphan authorization single-use index missing'; END IF;
 IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('specialist_profiles','specialist_services','specialist_settings','specialist_media','specialist_channel_sets','specialist_contact_channels','specialist_upload_control','specialist_upload_reservations','specialist_upload_audit','specialist_operator_identities','specialist_erasure_confirmations','specialist_erasure_authorizations') AND c.relrowsecurity AND c.relforcerowsecurity)<>12 THEN RAISE EXCEPTION 'Private tables missing FORCE RLS'; END IF;

 FOR p IN SELECT * FROM pg_policy WHERE polrelid='storage.objects'::regclass AND polname IN ('specialist_gateway_insert_only','specialist_gateway_update_only','specialist_gateway_delete_only') LOOP
  IF cardinality(p.polroles)<>2 OR ARRAY(SELECT rolname::text FROM pg_roles WHERE oid=ANY(p.polroles) ORDER BY rolname)<>ARRAY['anon','authenticated']::text[] THEN RAISE EXCEPTION 'Storage barrier role drift'; END IF;
  IF p.polcmd IS DISTINCT FROM (CASE p.polname WHEN 'specialist_gateway_insert_only' THEN 'a'::"char" WHEN 'specialist_gateway_update_only' THEN 'w'::"char" ELSE 'd'::"char" END) THEN RAISE EXCEPTION 'Storage barrier command drift'; END IF;
  IF p.polcmd IN ('w','d') AND regexp_replace(pg_get_expr(p.polqual,p.polrelid),'[()[:space:]]','','g') IS DISTINCT FROM 'bucket_idISDISTINCTFROM''specialist-media''::text' THEN RAISE EXCEPTION 'Storage barrier USING drift'; END IF;
  IF p.polcmd IN ('a','w') AND regexp_replace(pg_get_expr(p.polwithcheck,p.polrelid),'[()[:space:]]','','g') IS DISTINCT FROM 'bucket_idISDISTINCTFROM''specialist-media''::text' THEN RAISE EXCEPTION 'Storage barrier CHECK drift'; END IF;
 END LOOP;
 IF EXISTS(SELECT FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname LIKE 'specialist%' AND c.relkind='r' AND (has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE') OR has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE'))) THEN RAISE EXCEPTION 'Private table grant drift'; END IF;
 IF (SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE '%specialist%')<>33 THEN RAISE EXCEPTION 'Unexpected specialist RPC overload'; END IF;
 IF has_table_privilege('service_role','public.specialist_upload_audit','INSERT,UPDATE,DELETE') THEN RAISE EXCEPTION 'Audit mutation grant drift'; END IF;

 IF EXISTS(SELECT FROM pg_roles WHERE rolname='specialist_operator' AND (rolsuper OR rolcanlogin OR rolbypassrls OR rolcreaterole OR rolcreatedb OR rolinherit)) OR NOT EXISTS(SELECT FROM pg_roles WHERE rolname='specialist_operator') THEN RAISE EXCEPTION 'Operator role drift'; END IF;
 IF pg_has_role('service_role','specialist_operator','MEMBER') OR pg_has_role('authenticated','specialist_operator','MEMBER') OR pg_has_role('anon','specialist_operator','MEMBER') THEN RAISE EXCEPTION 'Operator role separation lost'; END IF;
 IF EXISTS(SELECT FROM pg_class c WHERE c.oid IN ('public.specialist_upload_audit'::regclass,'public.specialist_operator_identities'::regclass,'public.specialist_erasure_confirmations'::regclass,'public.specialist_erasure_authorizations'::regclass) AND (has_table_privilege('service_role',c.oid,'SELECT,INSERT,UPDATE,DELETE') OR has_table_privilege('specialist_operator',c.oid,'SELECT,INSERT,UPDATE,DELETE'))) THEN RAISE EXCEPTION 'Private operator table grant drift'; END IF;
 IF (SELECT count(*) FROM pg_policy WHERE polrelid='storage.objects'::regclass AND polname IN ('specialist_operator_read','specialist_operator_remove') AND polpermissive AND cardinality(polroles)=1 AND polroles[1]='specialist_operator'::regrole AND polcmd=CASE polname WHEN 'specialist_operator_read' THEN 'r'::"char" ELSE 'd'::"char" END)<>2 THEN RAISE EXCEPTION 'Operator Storage policy drift'; END IF;

 IF (SELECT count(*) FROM pg_policy WHERE polrelid='storage.objects'::regclass AND polname IN ('specialist_operator_scope_read','specialist_operator_scope_remove') AND NOT polpermissive AND cardinality(polroles)=1 AND polroles[1]='specialist_operator'::regrole AND polcmd=CASE polname WHEN 'specialist_operator_scope_read' THEN 'r'::"char" ELSE 'd'::"char" END)<>2 THEN RAISE EXCEPTION 'Restrictive operator Storage scope missing'; END IF;

END $post$;
COMMIT;
